// One Cloudflare Worker serves the Next.js app and scheduled monitoring.
// The OpenNext build generates this module before Wrangler deployment.
// @ts-ignore Generated by OpenNext during the build.
import handler from "./.open-next/worker.js";
import { runScheduledChecks } from "./src/lib/monitoring";

type MonitoringEnv = { MONITORING_ENABLED?: string; MONITOR_TARGETS?: string };

// Use minimal structural types to keep the Next.js typecheck independent of
// Cloudflare's ambient Worker types. Runtime provides these interfaces.
type ScheduledEvent = { scheduledTime: number; cron: string };
type WorkerContext = { waitUntil(promise: Promise<unknown>): void };

export default {
  fetch: handler.fetch,
  async scheduled(_event: ScheduledEvent, env: MonitoringEnv, ctx: WorkerContext) {
    ctx.waitUntil(runScheduledChecks(env));
  },
};
